using Microsoft.Data.Sqlite; using Workbench.Core.Workers; using Workbench.Storage.Database;
namespace Workbench.Storage.Workers;
public sealed class PermissionRepository(WorkbenchDatabase database){private readonly WorkbenchDatabase _d=database; public async Task AddAsync(Guid id,PermissionRequest p,CancellationToken ct=default){await using var c=_d.CreateConnection();await c.OpenAsync(ct);var q=c.CreateCommand();q.CommandText="INSERT INTO permission_requests(id,task_id,revision_number,requested_capability,scope,access_mode,reason,risk,requested_duration_seconds,state,created_at) VALUES($i,$t,$n,$c,$s,$a,$r,$k,$d,'Pending',$at)";q.Parameters.AddWithValue("$i",id.ToString());q.Parameters.AddWithValue("$t",p.TaskId.ToString());q.Parameters.AddWithValue("$n",p.RevisionNumber);q.Parameters.AddWithValue("$c",p.RequestedCapability);q.Parameters.AddWithValue("$s",p.Scope);q.Parameters.AddWithValue("$a",p.AccessMode.ToString());q.Parameters.AddWithValue("$r",p.Reason);q.Parameters.AddWithValue("$k",p.Risk.ToString());q.Parameters.AddWithValue("$d",(long)p.RequestedDuration.TotalSeconds);q.Parameters.AddWithValue("$at",p.CreatedAt.ToString("O"));await q.ExecuteNonQueryAsync(ct);}}
